TRIPLE_IDS = [(0, 1, 2), (0, 1, 3), (0, 1, 4), (0, 1, 5), (0, 1, 6), (0, 1, 7), (0, 1, 8), (0, 2, 3), (0, 2, 4), (0, 2, 5), (0, 2, 6), (0, 2, 7), (0, 2, 8), (0, 3, 4), (0, 3, 5), (0, 3, 6), (0, 3, 7), (0, 3, 8), (0, 4, 5), (0, 4, 6), (0, 4, 7), (0, 4, 8), (0, 5, 6), (0, 5, 7), (0, 5, 8), (0, 6, 7), (0, 6, 8), (0, 7, 8), (1, 2, 3), (1, 2, 4), (1, 2, 5), (1, 2, 6), (1, 2, 7), (1, 2, 8), (1, 3, 4), (1, 3, 5), (1, 3, 6), (1, 3, 7), (1, 3, 8), (1, 4, 5), (1, 4, 6), (1, 4, 7), (1, 4, 8), (1, 5, 6), (1, 5, 7), (1, 5, 8), (1, 6, 7), (1, 6, 8), (1, 7, 8), (2, 3, 4), (2, 3, 5), (2, 3, 6), (2, 3, 7), (2, 3, 8), (2, 4, 5), (2, 4, 6), (2, 4, 7), (2, 4, 8), (2, 5, 6), (2, 5, 7), (2, 5, 8), (2, 6, 7), (2, 6, 8), (2, 7, 8), (3, 4, 5), (3, 4, 6), (3, 4, 7), (3, 4, 8), (3, 5, 6), (3, 5, 7), (3, 5, 8), (3, 6, 7), (3, 6, 8), (3, 7, 8), (4, 5, 6), (4, 5, 7), (4, 5, 8), (4, 6, 7), (4, 6, 8), (4, 7, 8), (5, 6, 7), (5, 6, 8), (5, 7, 8), (6, 7, 8)]

def init_agent():
    return {'colors': jnp.full((9,), -1, jnp.int32),
            'positions': jnp.zeros((9, 2), jnp.int32),
            'turns': jnp.asarray(0, jnp.int32),
            'partner_seen': jnp.zeros((9,), jnp.bool_),
            'evidence': jnp.zeros((9, 9), jnp.float32)}


def beliefs(obs, colors, evidence):
    ASSIGN = jnp.asarray(ASSIGNMENTS, jnp.int32)
    TRIPLES = jnp.asarray(TRIPLE_IDS, jnp.int32)
    SAME = (ASSIGN[:, :, None] == ASSIGN[:, None, :]).astype(jnp.float32)
    TRIPLE_SAME = ((ASSIGN[:, TRIPLES[:, 0]] == ASSIGN[:, TRIPLES[:, 1]]) & (ASSIGN[:, TRIPLES[:, 0]] == ASSIGN[:, TRIPLES[:, 2]])).astype(jnp.float32)
    consistent = jnp.all((colors[None, :] < 0) | (colors[None, :] == ASSIGN), axis=1)
    hint_sets = obs.node_features[9:, 3:6]
    target = obs.adjacency_matrix[9:, :9].astype(jnp.float32)
    allowed = jnp.einsum('hi,hc->ic', target, hint_sets.astype(jnp.float32))
    hinted = jnp.sum(target, axis=0) > 0
    prob = jnp.where(hinted[None, :], jnp.where(allowed[jnp.arange(9)[None, :], ASSIGN] > 0, 0.98, 0.02), 1.)
    log_likelihood = jnp.einsum('ij,sij->s', evidence, SAME) * 0.5
    weights = consistent.astype(jnp.float32) * jnp.prod(prob, axis=1) * jnp.exp(log_likelihood - jnp.max(log_likelihood))
    weights = weights / jnp.maximum(jnp.sum(weights), 1e-20)
    marg = jnp.einsum('s,sic->ic', weights, jax.nn.one_hot(ASSIGN, 3))
    same = jnp.einsum('s,sij->ij', weights, SAME)
    triples = weights @ TRIPLE_SAME
    return weights, marg, same, triples


def geometry_score(positions, same, triples):
    TRIPLES = jnp.asarray(TRIPLE_IDS, jnp.int32)
    distances = jnp.abs(positions[..., :, None, :] - positions[..., None, :, :]).sum(-1)
    edges = distances == 1
    matches = jnp.sum(edges * same, axis=(-2, -1)) * 0.5
    a = distances[..., TRIPLES[:, 0], TRIPLES[:, 1]]
    b = distances[..., TRIPLES[:, 0], TRIPLES[:, 2]]
    c = distances[..., TRIPLES[:, 1], TRIPLES[:, 2]]
    mst = a + b + c - jnp.maximum(jnp.maximum(a, b), c)
    complete = ((a == 1).astype(jnp.int32) + (b == 1) + (c == 1)) == 2
    groups = jnp.sum(complete * triples, axis=-1)
    distance = jnp.sum(mst * triples, axis=-1)
    compact = jnp.sum(edges, axis=(-2, -1)) * 0.5
    return matches + 0.6 * groups - 0.12 * distance + 0.025 * compact


def agent_act(obs, reset, memory, rng):
    memory = jax.tree.map(lambda fresh, old: jnp.where(reset, fresh, old), init_agent(), memory)
    f = obs.node_features
    colors = jnp.where(f[:9, :3].sum(-1) > 0, jnp.argmax(f[:9, :3], axis=-1), memory['colors']).astype(jnp.int32)
    pos = obs.positions
    active = f[0, 10] > 0
    stage = f[0, 11]
    legal = obs.legal_actions
    adj = (jnp.abs(pos[:, None, :] - pos[None, :, :]).sum(-1) == 1)
    ASSIGN = jnp.asarray(ASSIGNMENTS, jnp.int32)
    SAME = (ASSIGN[:, :, None] == ASSIGN[:, None, :]).astype(jnp.float32)
    old_pos = memory['positions']
    old_adj = jnp.abs(old_pos[:, None, :] - old_pos[None, :, :]).sum(-1) == 1
    partner_seen = memory['partner_seen'] | (f[:9, 9] > 0)
    pair_confidence = 0.2 + 1.3 * (partner_seen[:, None] & partner_seen[None, :])
    delta = (adj.astype(jnp.float32) - old_adj.astype(jnp.float32)) * pair_confidence
    evidence = jnp.clip(memory['evidence'] + jnp.where((~active) & (~reset), delta, 0.), -2.5, 2.5)
    weights, marg, same, triples = beliefs(obs, colors, evidence)
    all_matches = jnp.einsum('ij,sij->s', adj.astype(jnp.float32), SAME) * 0.5
    pwin = jnp.sum(weights * (all_matches == 6))
    uncertainty = 1. - jnp.sum(marg * marg, axis=-1)
    degree = adj.sum(-1)
    changed = jnp.any(pos != memory['positions'], axis=-1) & ~reset
    info = uncertainty * (1. + 0.12 * degree + 0.4 * changed)
    info += jax.random.uniform(rng, (9,)) * 0.015
    observe_action = 1 + jnp.argmax(jnp.where(legal[1:10], info, -1e9))
    end_action = jnp.where((pwin > 0.65) & legal[1067], 1067, observe_action)

    CELLS = jnp.stack([jnp.arange(81) // 9, jnp.arange(81) % 9], axis=-1)
    MOVE_IDS = jnp.arange(729) // 81
    MOVE_DEST = CELLS[jnp.arange(729) % 81]
    candidates = jnp.broadcast_to(pos, (729, 9, 2)).at[jnp.arange(729), MOVE_IDS].set(MOVE_DEST)
    scores = geometry_score(candidates, same, triples)
    move_action = 10 + jnp.argmax(jnp.where(legal[10:739], scores, -1e9))

    hint_sets = f[9:, 3:6].astype(jnp.float32)
    correctness = hint_sets @ marg.T
    neighbors = jnp.sum(adj * same, axis=-1)
    known = jnp.max(marg, axis=-1)
    placement = 3. * correctness + 0.5 * neighbors[None, :] + 0.1 * known[None, :]
    placement += 0.15 * (jnp.sum(hint_sets, axis=-1) == 1)[:, None]
    place_ids = 743 + 81 * jnp.arange(4)[:, None] + pos[None, :, 0] * 9 + pos[None, :, 1]
    flat = jnp.argmax(jnp.where(legal[place_ids], placement, -1e9))
    place_action = place_ids.reshape(-1)[flat]
    reveal_action = 739 + jnp.argmax(legal[739:743])
    singleton_safe = legal[place_ids[0]] & (correctness[0] > 0.98) & (colors >= 0) & (jnp.max(adj * same, axis=-1) > 0.9)
    singleton_card = jnp.argmax(jnp.where(singleton_safe, placement[0] + 0.3 * (~partner_seen), -1e9))
    early_place = place_ids[0, singleton_card]
    hint_action = jnp.where(jnp.any(legal[739:743]), reveal_action, place_action)
    hint_action = jnp.where(jnp.any(singleton_safe), early_place, hint_action)
    action = jnp.where(stage < 2, end_action, jnp.where(stage == 2, move_action, hint_action))
    action = jnp.where(active, action, 0).astype(jnp.int32)
    new_memory = {'colors': colors, 'positions': pos, 'turns': memory['turns'] + ((stage == 3) & active).astype(jnp.int32),
                  'partner_seen': partner_seen, 'evidence': evidence}
    return action, new_memory, {'colors': colors, 'pwin': pwin, 'marginal': marg,
                                'value': geometry_score(pos, same, triples)}
